:root {
  color-scheme: light dark;
  --bg: #ffffff;
  --bg-subtle: #f5f5f7;
  --border: #e0e0e3;
  --text: #1c1c1e;
  --text-muted: #6b6b70;
  --accent: #0a66ff;
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --badge-observed: #2f7d32;
  --badge-parsed: #a15c00;
  --badge-inferred: #5c5cd6;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #1e1e1e;
    --bg-subtle: #2a2a2c;
    --border: #3a3a3d;
    --text: #f0f0f2;
    --text-muted: #9a9a9e;
    --badge-observed: #6bd06f;
    --badge-parsed: #e0a84a;
    --badge-inferred: #a9a9f5;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--sans);
  background: var(--bg);
  color: var(--text);
  font-size: 13px;
}

h1, h2, h3 {
  margin: 0;
  font-weight: 600;
}

.section {
  border-bottom: 1px solid var(--border);
  padding: 10px 14px;
}

.section:last-child {
  border-bottom: none;
}

.section-title {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted);
  margin-bottom: 6px;
}

.row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding: 3px 0;
}

.row-label {
  color: var(--text-muted);
  white-space: nowrap;
  flex: 0 0 auto;
}

.row-value-group {
  display: flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
  overflow: hidden;
}

.row-value {
  font-family: var(--mono);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.badge {
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  padding: 1px 5px;
  border-radius: 3px;
  border: 1px solid currentColor;
  flex: 0 0 auto;
}

.badge-observed { color: var(--badge-observed); }
.badge-parsed { color: var(--badge-parsed); }
.badge-inferred { color: var(--badge-inferred); }

.copy-btn {
  border: none;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 12px;
  line-height: 1;
  padding: 2px 4px;
  border-radius: 3px;
  flex: 0 0 auto;
}

.copy-btn:hover {
  background: var(--bg-subtle);
  color: var(--text);
}

.copy-btn.copied {
  color: var(--badge-observed);
}

.empty-state {
  color: var(--text-muted);
  padding: 24px 14px;
  text-align: center;
}

details.raw-headers {
  padding: 10px 14px;
}

details.raw-headers summary {
  cursor: pointer;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted);
}

.raw-headers pre {
  margin: 8px 0 0;
  font-family: var(--mono);
  font-size: 11px;
  white-space: pre-wrap;
  word-break: break-all;
  background: var(--bg-subtle);
  border-radius: 6px;
  padding: 8px;
  max-height: 220px;
  overflow-y: auto;
}

.provider-chip {
  display: inline-block;
  font-weight: 600;
}

